// Parse MQTT payload
const payload = JSON.parse($input.item.json.payload);
const text = payload.text.toLowerCase();
const user = payload.user;
const confidence = payload.confidence;

// Log the command
console.log(`Voice command from ${user}: "${text}" (confidence: ${confidence})`);

// Command parsing logic
let haService = null;
let entityId = null;
let serviceData = {};

// Kitchen light commands
if (text.includes('kitchen') && text.includes('light')) {
  if (text.includes('on') || text.includes('turn on')) {
    haService = 'light/turn_on';
    entityId = 'light.kitchen_light';
  } else if (text.includes('off') || text.includes('turn off')) {
    haService = 'light/turn_off';
    entityId = 'light.kitchen_light';
  }
}

// Living room light commands
else if (text.includes('living room') && text.includes('light')) {
  if (text.includes('on')) {
    haService = 'light/turn_on';
    entityId = 'light.living_room_light';
  } else if (text.includes('off')) {
    haService = 'light/turn_off';
    entityId = 'light.living_room_light';
  }
}

// Temperature query
else if (text.includes('temperature') || text.includes('how hot') || text.includes('how cold')) {
  haService = 'sensor/get_state';
  entityId = 'sensor.living_room_temperature';
}

// Lock/unlock door
else if (text.includes('door')) {
  if (text.includes('lock')) {
    haService = 'lock/lock';
    entityId = 'lock.front_door';
  } else if (text.includes('unlock')) {
    haService = 'lock/unlock';
    entityId = 'lock.front_door';
  }
}

// Scene activation
else if (text.includes('movie time') || text.includes('movie mode')) {
  haService = 'scene/turn_on';
  entityId = 'scene.movie_time';
}

// If no command matched
if (!haService) {
  return {
    json: {
      error: 'Command not recognized',
      originalText: text,
      skip: true
    }
  };
}

// Return parsed command for Home Assistant
return {
  json: {
    service: haService,
    entity_id: entityId,
    service_data: serviceData,
    originalCommand: payload
  }
};

// Log successful execution
const command = $input.first().json.originalCommand;
const haResponse = $input.first().json;

console.log('Successfully executed voice command:', command.text);
console.log('Home Assistant response:', haResponse);

return {
  json: {
    success: true,
    command: command.text,
    user: command.user,
    timestamp: command.timestamp
  }
};
